/// `scopes_grant_access`.
pub fn scopes_grant_access(scopes: &[Vec<u8>], required_scope: &[u8]) -> bool {
    let has_admin_wildcard = any_eq(scopes, b"*") || any_eq(scopes, b"admin");
    if any_eq(scopes, required_scope) || has_admin_wildcard {
        return true;
    }
    match split_once(required_scope, b':') {
        Some((parent, _resource)) => parent.len() > 0 && any_eq(scopes, &parent),
        None => false,
    }
}

/// `list.iter().any(|x| x == s)`.
pub fn any_eq(list: &[Vec<u8>], s: &[u8]) -> bool {
    let mut i = 0;
    while i < list.len() {
        if bytes_eq(&list[i], s) {
            return true;
        }
        i += 1;
    }
    false
}

/// `s.split_once(sep)`.
pub fn split_once(s: &[u8], sep: u8) -> Option<(Vec<u8>, Vec<u8>)> {
    match find_byte(s, sep) {
        Some(i) => Some((sub(s, 0, i), sub(s, i + 1, s.len()))),
        None => None,
    }
}

/// `s.find(b)`.
pub fn find_byte(s: &[u8], b: u8) -> Option<usize> {
    let mut i = 0;
    while i < s.len() {
        if s[i] == b {
            return Some(i);
        }
        i += 1;
    }
    None
}

/// `s[a..b]`, owned; empty when the range is out of order.
pub fn sub(s: &[u8], a: usize, b: usize) -> Vec<u8> {
    let mut out = Vec::new();
    let mut i = a;
    while i < b && i < s.len() {
        out.push(s[i]);
        i += 1;
    }
    out
}

