#[test]
fn scopes_grant_access_spec() {
    let mut r = Rng(117);
    let (mut yes, mut no) = (0, 0);
    const S: &[&str] = &["read", "write", "read:artifacts", "write:artifacts", "admin", "*", ":x", "write:",
                         "", "a:b:c", "a", "Admin", "x:"];
    for _ in 0..2_000_000 {
        let scopes: Vec<Vec<u8>> = (0..r.below(4)).map(|_| b(r.pick(S))).collect();
        let req = b(r.pick(S));
        let got = k::token_scope::scopes_grant_access(&scopes, &req);
        assert_eq!(got, scope_grants(&scopes, &req), "{scopes:?} {req:?}");
        if got { yes += 1 } else { no += 1 }
    }
    assert!(yes >= MIN_HITS && no >= MIN_HITS);
}

#[test]
fn scopes_agree() {
    use crate::services::token_service as ts;
    let mut r = Rng(11);
    let mut granted = 0;
    for _ in 0..1_000_000 {
        let scopes = scope_list(&mut r);
        let ks: Vec<Vec<u8>> = scopes.iter().map(|s| b(s)).collect();
        let req = scope_list(&mut r).pop().unwrap_or_default();
        let g = k::token_scope::scopes_grant_access(&ks, &b(&req));
        assert_eq!(g, ts::scopes_grant_access(&scopes, &req), "{scopes:?} {req:?}");
        granted += g as usize;
        assert_eq!(k::token_scope::validate_scopes_pure(&ks).is_ok(), ts::validate_scopes_pure(&scopes).is_ok());
        let admin = r.chance(50);
        let got = k::token_scope::enforce_admin_only_scopes(&ks, admin);
        let want = ts::enforce_admin_only_scopes(&scopes, admin);
        assert_eq!(got.is_ok(), want.is_ok());
        if let (Err(s), Err(msg)) = (got, want) {
            assert!(msg.starts_with(&format!("Scope '{}'", String::from_utf8(s).unwrap())), "{msg}");
        }
    }
    assert!(granted > 1000);
}

/// The credential tables. `base64` and `ip` are filled per request.
pub fn oracle(r: &mut Rng, db: &Db) -> k::trusted::Oracle {
    let jwt = ["j1", "j2"].iter().filter(|_| r.chance(80)).collect::<Vec<_>>().into_iter().map(|t| (b(t), k::Claims {
        sub: r.pick(&USERS),
        username: b(r.pick(&NAMES)),
        email: b("e@x"),
        is_admin: r.chance(40),
        allowed_repo_ids: if r.chance(50) { None } else { Some(r.subset(&REPOS, 40)) },
        iat: match r.below(4) { 0 => i64::MAX / 999, 1 => i64::MIN / 999, _ => r.below(1000) as i64 },
        iat_ms: if r.chance(30) { Some(r.below(5000) as i64) } else { None },
        scopes: if r.chance(40) { None } else { Some(scopes(r)) },
    })).collect();
    let api_tokens = ["t1", "t2", "t3"].iter().filter(|_| r.chance(85)).collect::<Vec<_>>().into_iter().map(|t| (b(t), if r.chance(75) {
        Ok(k::trusted::ApiTokenValidation {
            user: db.users[r.below(4) as usize].clone(),
            scopes: scopes(r),
            allowed_repo_ids: access(r),
        })
    } else {
        Err(auth_err(r))
    })).collect();
    let passwords = [("alice", "pw"), ("bob", "j1"), ("carol", "t2"), ("dave", "bad")].iter()
        .filter(|_| r.chance(85))
        .collect::<Vec<_>>().into_iter()
        .map(|(u, p)| (b(u), b(p), if r.chance(55) { Ok(db.users[r.below(4) as usize].clone()) } else { Err(auth_err(r)) }))
        .collect();
    k::trusted::Oracle { jwt, api_tokens, passwords, base64: vec![], ip: vec![] }
}
